const { tokenize, evaluate } = require('./s6_parser');

// Test cases
console.log("Testing tokenize function...");

// Test 1: Simple addition
try {
  const result1 = tokenize("1 + 2");
  console.assert(JSON.stringify(result1) === JSON.stringify(["1", "+", "2"]), "Test 1 failed");
  console.log("✓ Test 1 passed: Simple addition");
} catch (e) {
  console.error("✗ Test 1 failed:", e.message);
}

// Test 2: Decimal numbers
try {
  const result2 = tokenize("3.14 + 2.86");
  console.assert(JSON.stringify(result2) === JSON.stringify(["3.14", "+", "2.86"]), "Test 2 failed");
  console.log("✓ Test 2 passed: Decimal numbers");
} catch (e) {
  console.error("✗ Test 2 failed:", e.message);
}

// Test 3: Complex expression
try {
  const result3 = tokenize("(1 + 2) * 3");
  console.assert(JSON.stringify(result3) === JSON.stringify(["(", "1", "+", "2", ")", "*", "3"]), "Test 3 failed");
  console.log("✓ Test 3 passed: Complex expression");
} catch (e) {
  console.error("✗ Test 3 failed:", e.message);
}

// Test 4: Division and subtraction
try {
  const result4 = tokenize("10 / 2 - 3");
  console.assert(JSON.stringify(result4) === JSON.stringify(["10", "/", "2", "-", "3"]), "Test 4 failed");
  console.log("✓ Test 4 passed: Division and subtraction");
} catch (e) {
  console.error("✗ Test 4 failed:", e.message);
}

// Test 5: Invalid character should throw error
try {
  tokenize("1 + 2 & 3");
  console.error("✗ Test 5 failed: Should have thrown error for invalid character");
} catch (e) {
  console.assert(e.message === "Invalid character: &", "Test 5 failed: Wrong error message");
  console.log("✓ Test 5 passed: Invalid character throws error");
}

// Test 6: Empty string
try {
  const result6 = tokenize("");
  console.assert(JSON.stringify(result6) === JSON.stringify([]), "Test 6 failed");
  console.log("✓ Test 6 passed: Empty string");
} catch (e) {
  console.error("✗ Test 6 failed:", e.message);
}

// Test 7: Whitespace handling
try {
  const result7 = tokenize("  1  +  2  ");
  console.assert(JSON.stringify(result7) === JSON.stringify(["1", "+", "2"]), "Test 7 failed");
  console.log("✓ Test 7 passed: Whitespace handling");
} catch (e) {
  console.error("✗ Test 7 failed:", e.message);
}

// Test 8: Variable evaluation
try {
  const result8 = evaluate("x + y", { x: 5, y: 3 });
  console.assert(result8 === 8, "Test 8 failed: Variable evaluation");
  console.log("✓ Test 8 passed: Variable evaluation");
} catch (e) {
  console.error("✗ Test 8 failed:", e.message);
}

// Test 9: Unknown variable should throw error
try {
  evaluate("x + 1", { y: 5 });
  console.error("✗ Test 9 failed: Should have thrown error for unknown variable");
} catch (e) {
  console.assert(e.message === "Unknown variable: x", "Test 9 failed: Wrong error message");
  console.log("✓ Test 9 passed: Unknown variable throws error");
}

// Test 10: Variable with underscore
try {
  const result10 = evaluate("my_var + 10", { my_var: 5 });
  console.assert(result10 === 15, "Test 10 failed: Variable with underscore");
  console.log("✓ Test 10 passed: Variable with underscore");
} catch (e) {
  console.error("✗ Test 10 failed:", e.message);
}

// Test 11: Variable with digits
try {
  const result11 = evaluate("var1 + var2", { var1: 10, var2: 20 });
  console.assert(result11 === 30, "Test 11 failed: Variables with digits");
  console.log("✓ Test 11 passed: Variables with digits");
} catch (e) {
  console.error("✗ Test 11 failed:", e.message);
}

// Test 12: Existing functionality still works (no vars parameter)
try {
  const result12 = evaluate("2 + 3 * 4");
  console.assert(result12 === 14, "Test 12 failed: Existing functionality");
  console.log("✓ Test 12 passed: Existing functionality still works");
} catch (e) {
  console.error("✗ Test 12 failed:", e.message);
}

console.log("All tests completed!");

